        best_global = None  # (delta, i, pos, j, new_from, new_to)

        for i in range(n):
            ri = routes[i]
            if not ri:
                continue
            li = loads[i]
            cost_from_old = route_cost(ri)
            for pos in range(len(ri)):
                node = ri[pos]
                new_from = ri[:pos] + ri[pos + 1:]
                cost_from_new = route_cost(new_from)
                # candidate destination routes based on proximity
                cand_routes = set()
                for u in nearest.get(node, []):
                    if u in where:
                        cand_routes.add(where[u])
                cand_routes.add(i)
                cand_routes = [j for j in cand_routes if j != i and routes[j]]
                cand_routes.sort()
                for j in cand_routes:
                    if loads[j] + demands[node] > capacity:
                        continue
                    ins = best_insertion_into_route(node, routes[j])
                    if ins is None:
                        continue
                    cost_to_old = route_cost(routes[j])
                    cost_to_new, new_to = ins
                    delta = (cost_from_new + cost_to_new) - (cost_from_old + cost_to_old)
                    if best_global is None or delta < best_global[0]:
                        best_global = (delta, i, pos, j, new_from, new_to)

        if best_global is None:
            return False

        delta, i, pos, j, new_from, new_to = best_global

        if delta >= 0:
            if hint is not None and hint > 0 and len(routes) > hint + 1:
                # allow mild non-improvement only when we are above hint
                if delta > 0.01 * total_cost(routes):
                    return False
            else:
                return False

        # apply move
        node = routes[i][pos]
        routes[i] = new_from
        routes[j] = new_to
        if not routes[i]:
            routes.pop(i)
        return True

    for _ in range(40):
        if len(routes) <= 1:
            break
        if not inter_relocate(routes):
            break

    # Additional focused edit: inter-route swap (exchange one customer between two routes)
    def inter_exchange(routes):
        n = len(routes)
        if n <= 1:
            return False

        loads = [route_load(r) for r in routes]
        cust_list = list(instance["customer_ids"])
        topk = 6
        nearest = {}
        for v in cust_list:
            dv = []
            row_v = matrix[v]
            for u in cust_list:
                if u == v:
                    continue
                dv.append((row_v[u], u))
            dv.sort(key=lambda x: (x[0], x[1]))
            nearest[v] = [u for _, u in dv[:topk]]

        where = {}
        for i in range(n):
            for v in routes[i]:
                where[v] = i

        best = None  # (delta, i, pos_i, j, pos_j, new_i, new_j)

        for i in range(n):
            if not routes[i]:
                continue
            ri = routes[i]
            cost_i_old = route_cost(ri)
            for pos_i in range(len(ri)):
                a = ri[pos_i]
                # candidate routes for swapping are those containing nearest neighbors of a
                cand_routes = set()
                for u in nearest.get(a, []):
                    if u in where:
                        cand_routes.add(where[u])
                cand_routes = [j for j in cand_routes if j != i and routes[j]]
                cand_routes.sort()
                for j in cand_routes:
                    rj = routes[j]
                    cost_j_old = route_cost(rj)
                    # find positions of candidate b in route j: limited to nearest neighbors in rj
                    for pos_j in range(len(rj)):
                        b = rj[pos_j]
                        if j != where.get(b, j):
                            continue
                        li2 = loads[i] - demands[a] + demands[b]
                        lj2 = loads[j] - demands[b] + demands[a]
                        if li2 > capacity or lj2 > capacity:
                            continue
                        new_ri = ri[:pos_i] + [b] + ri[pos_i + 1:]
                        new_rj = rj[:pos_j] + [a] + rj[pos_j + 1:]
                        delta = (route_cost(new_ri) + route_cost(new_rj)) - (cost_i_old + cost_j_old)
                        if best is None or delta < best[0]:
                            best = (delta, i, pos_i, j, pos_j, new_ri, new_rj)

        if best is None:
            return False

        delta, i, pos_i, j, pos_j, new_i, new_j = best
        if delta >= 0:
            if hint is not None and hint > 0 and len(routes) > hint + 1:
                if delta > 0.01 * total_cost(routes):
                    return False
            else:
                return False

        routes[i] = new_i
        routes[j] = new_j
        return True

    for _ in range(25):
        if len(routes) <= 1:
            break
        if not inter_exchange(routes):
            break

    # final cleanup: remove empty routes
    routes = [r for r in routes if r]

    # small final intra-route polish
    for idx in range(len(routes)):
        if len(routes[idx]) >= 4:
            routes[idx] = two_opt_improve(routes[idx])

    return routes
